// Nails by Glossy Six: one-command updater (includes your photos).
// Put this file in your project folder (next to package.json), then run:  node update.mjs
import fs from "node:fs";
import path from "node:path";

const files = {
 "vite.config.js": "import { defineConfig } from \"vite\";\nimport react from \"@vitejs/plugin-react\";\n\nexport default defineConfig({\n  plugins: [react()],\n  server: { proxy: { \"/api\": \"http://localhost:3001\" } },\n});\n",
 "tailwind.config.js": "/** Soft palette: pink, white and nude (from the brand concept). Edit here to retheme. */\nexport default {\n  content: [\"./index.html\", \"./src/**/*.{js,jsx}\"],\n  theme: {\n    extend: {\n      colors: {\n        petal: \"#FFF7F5\", // page background\n        blush: \"#F7D6DC\", // soft pink surfaces\n        nude: \"#EBD3C6\",  // nude surfaces\n        rose: \"#B4506A\",  // buttons / links (readable on white)\n        berry: \"#4A2630\", // text\n        gold: \"#B8935A\",  // small decorative accents (matches the logo)\n      },\n      fontFamily: {\n        display: ['\"Lora\"', \"Georgia\", \"serif\"],         // headings (like your menu poster)\n        script: ['\"Yellowtail\"', \"cursive\"],             // brand name and accents (like your logo)\n        body: ['\"Nunito\"', \"system-ui\", \"sans-serif\"],   // subtext: soft, rounded, easy to read\n      },\n    },\n  },\n  plugins: [],\n};\n",
 "README.md": "# Nails by Glossy Six\n\nReact + Tailwind CSS + Node/Express.\n\n## Run it\n```\nnpm install\nnpm run dev      # site at http://localhost:5173, API at :3001\n```\nProduction: `npm run build && npm start` (Express serves the site at http://localhost:3001).\n\n## Edit your content\n- `src/data.js`: email, address, social links, services and prices (prices are placeholders)\n- `tailwind.config.js`: colors and fonts\n- Contact messages are saved to `server/messages.json` and bookings to `server/bookings.json`. To receive them by email, add `nodemailer` in `server/index.js`.\n- Map location: `mapQuery` in `src/data.js`\n\n## Admin\nGo to `/admin` (there is a small \"Admin\" link in the footer). Default login: **admin / glossy2026**.\nCHANGE IT before going online by setting environment variables `ADMIN_USER`, `ADMIN_PASS` and `SECRET`\n(Windows PowerShell example: `$env:ADMIN_PASS=\"my-strong-password\"; npm start`).\nBookings and receipts are stored in `server/data.json`. Back this file up.\n\n## Demo on Vercel (no server needed)\n`vercel.json` builds the site in DEMO MODE (`VITE_DEMO=true`): bookings, reviews and the admin work, but data is saved only in\nthe visitor's own browser (`src/demoApi.js`). Demo admin login: admin / glossy2026. For real customers, run the Node server\n(`npm start`) with a real database instead, and remove `VITE_DEMO` from the build command.\n",
 "index.html": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <meta name=\"description\" content=\"Nails by Glossy Six: cute, creative and affordable nail art in San Fernando, Pampanga.\" />\n    <title>Nails by Glossy Six</title>\n    <link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><text y=%22.9em%22 font-size=%2290%22>💅</text></svg>\" />\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n    <link href=\"https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,500;0,600;0,700;1,500;1,600&family=Nunito:wght@400;500;600;700;800&family=Yellowtail&display=swap\" rel=\"stylesheet\" />\n  </head>\n  <body>\n    <div id=\"root\"></div>\n    <script type=\"module\" src=\"/src/main.jsx\"></script>\n  </body>\n</html>\n",
 "vercel.json": "{\n  \"buildCommand\": \"VITE_DEMO=true npm run build\",\n  \"outputDirectory\": \"dist\",\n  \"rewrites\": [{ \"source\": \"/(.*)\", \"destination\": \"/index.html\" }]\n}\n",
 ".gitignore": "node_modules\ndist\nserver/messages.json\nserver/bookings.json\nserver/data.json\n",
 "postcss.config.js": "export default { plugins: { tailwindcss: {}, autoprefixer: {} } };\n",
 "package.json": "{\n  \"name\": \"nails-by-glossy-six\",\n  \"private\": true,\n  \"version\": \"1.0.0\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"concurrently \\\"vite\\\" \\\"node --watch server/index.js\\\"\",\n    \"build\": \"vite build\",\n    \"start\": \"node server/index.js\"\n  },\n  \"dependencies\": {\n    \"express\": \"^4.19.2\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"react-router-dom\": \"^6.26.0\"\n  },\n  \"devDependencies\": {\n    \"@vitejs/plugin-react\": \"^4.3.1\",\n    \"autoprefixer\": \"^10.4.20\",\n    \"concurrently\": \"^8.2.2\",\n    \"postcss\": \"^8.4.41\",\n    \"tailwindcss\": \"^3.4.10\",\n    \"vite\": \"^5.4.2\"\n  }\n}\n",
 "server/index.js": "import express from \"express\";\nimport crypto from \"node:crypto\";\nimport fs from \"node:fs\";\nimport path from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\n\nconst __dirname = path.dirname(fileURLToPath(import.meta.url));\nconst app = express();\nconst PORT = process.env.PORT || 3001;\n\n// ---- Admin login (CHANGE THESE: set ADMIN_USER / ADMIN_PASS / SECRET environment variables) ----\nconst ADMIN_USER = process.env.ADMIN_USER || \"admin\";\nconst ADMIN_PASS = process.env.ADMIN_PASS || \"glossy2026\";\nconst SECRET = process.env.SECRET || crypto.randomBytes(32).toString(\"hex\");\nif (!process.env.ADMIN_PASS) console.warn(\"WARNING: using the default admin password. Set ADMIN_PASS before going online.\");\n\nconst h = (s) => crypto.createHash(\"sha256\").update(String(s)).digest();\nconst same = (a, b) => crypto.timingSafeEqual(h(a), h(b));\nconst sign = (p) => crypto.createHmac(\"sha256\", SECRET).update(p).digest(\"hex\");\nconst makeToken = () => { const p = String(Date.now() + 8 * 3600e3); return `${p}.${sign(p)}`; };\nconst validToken = (t) => {\n  const [p, s] = String(t || \"\").split(\".\");\n  if (!p || !s) return false;\n  const e = sign(p);\n  return s.length === e.length && crypto.timingSafeEqual(Buffer.from(s), Buffer.from(e)) && Number(p) > Date.now();\n};\nconst auth = (req, res, next) =>\n  validToken((req.headers.authorization || \"\").replace(\"Bearer \", \"\")) ? next() : res.status(401).json({ error: \"Please log in.\" });\n\n// ---- Tiny JSON \"database\" ----\nconst DB = path.join(__dirname, \"data.json\");\nconst read = () => ({ bookings: [], receipts: [], reviews: [], ...(fs.existsSync(DB) ? JSON.parse(fs.readFileSync(DB, \"utf8\")) : {}) });\nconst write = (d) => fs.writeFileSync(DB, JSON.stringify(d, null, 2));\n\nconst str = (v, max) => (typeof v === \"string\" ? v.trim().slice(0, max) : \"\");\nconst oneOf = (v, list, d) => (list.includes(v) ? v : d);\nconst cleanBooking = (b = {}) => {\n  const v = {\n    name: str(b.name, 100), address: str(b.address, 300), service: str(b.service, 100),\n    type: oneOf(b.type, [\"walk-in\", \"appointment\"], \"walk-in\"),\n    status: oneOf(b.status, [\"pending\", \"confirmed\", \"done\", \"cancelled\"], \"pending\"),\n    date: str(b.date, 10),\n  };\n  return !v.name || !v.service ? { error: \"Name and service are required.\" } : v;\n};\nconst cleanReceipt = (b = {}) => {\n  const v = {\n    bookingId: str(b.bookingId, 60), clientName: str(b.clientName, 100), service: str(b.service, 100),\n    amount: Number(b.amount), method: oneOf(b.method, [\"Cash\", \"GCash\", \"Other\"], \"Cash\"),\n    notes: str(b.notes, 300), date: str(b.date, 10),\n  };\n  return !v.clientName || !v.service || !Number.isFinite(v.amount) || v.amount < 0\n    ? { error: \"Client name, service and a valid amount are required.\" } : v;\n};\n\nconst cleanReview = (b = {}) => {\n  const v = {\n    name: str(b.name, 60), rating: Math.round(Number(b.rating)), comment: str(b.comment, 500),\n    status: oneOf(b.status, [\"pending\", \"approved\", \"hidden\"], \"pending\"),\n  };\n  return !v.name || !v.comment || !(v.rating >= 1 && v.rating <= 5)\n    ? { error: \"Please add your name, a rating from 1 to 5, and a comment.\" } : v;\n};\n\napp.use(express.json({ limit: \"10kb\" }));\n\n// ---- Public ----\napp.post(\"/api/contact\", (req, res) => {\n  const { name, email, message } = req.body || {};\n  if (!str(name, 100) || !/^\\S+@\\S+\\.\\S+$/.test(str(email, 200)) || !str(message, 2000)) {\n    return res.status(400).json({ error: \"Please fill in your name, a valid email, and a message.\" });\n  }\n  const f = path.join(__dirname, \"messages.json\");\n  const list = fs.existsSync(f) ? JSON.parse(fs.readFileSync(f, \"utf8\")) : [];\n  list.push({ name: str(name, 100), email: str(email, 200), message: str(message, 2000), at: new Date().toISOString() });\n  fs.writeFileSync(f, JSON.stringify(list, null, 2));\n  res.json({ ok: true });\n});\n\napp.post(\"/api/book\", (req, res) => {\n  const b = req.body || {};\n  if (!str(b.name, 100) || !str(b.address, 300) || !str(b.service, 100)) {\n    return res.status(400).json({ error: \"Please fill in your name, address and service.\" });\n  }\n  const d = read();\n  d.bookings.push({\n    id: crypto.randomUUID(), createdAt: new Date().toISOString(), type: \"appointment\", status: \"pending\", date: \"\",\n    name: str(b.name, 100), address: str(b.address, 300), service: str(b.service, 100),\n  });\n  write(d);\n  res.json({ ok: true });\n});\n\n// Customers see approved reviews only; new reviews wait for your approval\napp.get(\"/api/reviews\", (_req, res) => {\n  res.json(read().reviews.filter((r) => r.status === \"approved\").map(({ id, name, rating, comment, createdAt }) => ({ id, name, rating, comment, createdAt })));\n});\nconst reviewTries = new Map();\napp.post(\"/api/reviews\", (req, res) => {\n  const now = Date.now();\n  const recent = (reviewTries.get(req.ip) || []).filter((t) => now - t < 3600e3);\n  if (recent.length >= 5) return res.status(429).json({ error: \"Too many reviews from this device. Please try again later.\" });\n  const v = cleanReview({ ...req.body, status: \"pending\" });\n  if (v.error) return res.status(400).json(v);\n  reviewTries.set(req.ip, [...recent, now]);\n  const d = read();\n  d.reviews.push({ id: crypto.randomUUID(), createdAt: new Date().toISOString(), ...v });\n  write(d);\n  res.json({ ok: true });\n});\n\n// ---- Admin ----\nconst tries = new Map();\napp.post(\"/api/admin/login\", (req, res) => {\n  const t = tries.get(req.ip) || { n: 0, at: Date.now() };\n  if (Date.now() - t.at > 15 * 60e3) { t.n = 0; t.at = Date.now(); }\n  if (t.n >= 10) return res.status(429).json({ error: \"Too many tries. Please wait 15 minutes.\" });\n  const { username, password } = req.body || {};\n  if (same(username, ADMIN_USER) && same(password, ADMIN_PASS)) { tries.delete(req.ip); return res.json({ token: makeToken() }); }\n  t.n++; tries.set(req.ip, t);\n  res.status(401).json({ error: \"Wrong username or password.\" });\n});\n\n// Full CRUD for bookings and receipts\nfunction crud(name, clean) {\n  const base = `/api/admin/${name}`;\n  app.get(base, auth, (_q, res) => res.json(read()[name]));\n  app.post(base, auth, (req, res) => {\n    const v = clean(req.body);\n    if (v.error) return res.status(400).json(v);\n    const d = read();\n    const item = { id: crypto.randomUUID(), createdAt: new Date().toISOString(), ...v };\n    if (name === \"receipts\") {\n      const max = d.receipts.reduce((m, r) => Math.max(m, parseInt(String(r.no).slice(3)) || 0), 0);\n      item.no = \"GS-\" + String(max + 1).padStart(4, \"0\");\n    }\n    d[name].push(item); write(d); res.json(item);\n  });\n  app.put(`${base}/:id`, auth, (req, res) => {\n    const d = read(); const i = d[name].findIndex((x) => x.id === req.params.id);\n    if (i < 0) return res.status(404).json({ error: \"Not found.\" });\n    const v = clean({ ...d[name][i], ...req.body });\n    if (v.error) return res.status(400).json(v);\n    d[name][i] = { ...d[name][i], ...v }; write(d); res.json(d[name][i]);\n  });\n  app.delete(`${base}/:id`, auth, (req, res) => {\n    const d = read(); d[name] = d[name].filter((x) => x.id !== req.params.id); write(d); res.json({ ok: true });\n  });\n}\ncrud(\"bookings\", cleanBooking);\ncrud(\"receipts\", cleanReceipt);\ncrud(\"reviews\", cleanReview);\n\n// ---- Serve the built React app in production ----\nconst dist = path.join(__dirname, \"..\", \"dist\");\nif (fs.existsSync(dist)) {\n  app.use(express.static(dist));\n  app.get(\"*\", (_req, res) => res.sendFile(path.join(dist, \"index.html\")));\n}\n\napp.listen(PORT, () => console.log(`Server running on http://localhost:${PORT}`));\n",
 "src/demoApi.js": "// DEMO MODE: a tiny fake server that runs inside the browser and saves to localStorage.\n// It lets the site (bookings, reviews, admin) work on a static host like Vercel with no backend.\n// Turned on by the VITE_DEMO=true build setting. The real server is server/index.js.\nconst KEY = \"gs_demo_db_v1\";\nconst iso = () => new Date().toISOString();\n\nconst seed = () => {\n  const d = iso(), day = d.slice(0, 10);\n  const b = (id, name, address, service, type, status) => ({ id, createdAt: d, name, address, service, type, status, date: day });\n  return {\n    n: 10,\n    bookings: [\n      b(\"b1\", \"Ana Reyes\", \"San Agustin\", \"Classic French\", \"appointment\", \"pending\"),\n      b(\"b2\", \"Bea Cruz\", \"Dolores\", \"Detailed Art\", \"appointment\", \"confirmed\"),\n      b(\"b3\", \"Cathy Lim\", \"Telabastagan\", \"Natural / Plain\", \"walk-in\", \"done\"),\n      b(\"b4\", \"Dana Ruiz\", \"Sindalan\", \"Builder Gel (With Color)\", \"walk-in\", \"done\"),\n    ],\n    receipts: [{ id: \"r1\", no: \"GS-0001\", createdAt: d, clientName: \"Cathy Lim\", service: \"Natural / Plain\", amount: 350, method: \"Cash\", notes: \"\", date: day, bookingId: \"b3\" }],\n    reviews: [],\n  };\n};\n\nlet db = null;\ntry { db = JSON.parse(localStorage.getItem(KEY)); } catch { db = null; }\nif (!db || !db.bookings) db = seed();\nconst persist = () => { try { localStorage.setItem(KEY, JSON.stringify(db)); } catch { /* ignore */ } };\n\nconst reply = (data, status = 200) =>\n  Promise.resolve(new Response(JSON.stringify(data), { status, headers: { \"Content-Type\": \"application/json\" } }));\nconst s = (v, max) => (typeof v === \"string\" ? v.trim().slice(0, max) : \"\");\nconst uid = () => `id${(db.n++).toString(36)}${Math.random().toString(36).slice(2, 6)}`;\nconst valid = {\n  bookings: (b) => s(b.name, 100) && s(b.service, 100),\n  receipts: (b) => s(b.clientName, 100) && s(b.service, 100) && Number.isFinite(Number(b.amount)) && Number(b.amount) >= 0,\n  reviews: (b) => s(b.name, 60) && s(b.comment, 500) && Number(b.rating) >= 1 && Number(b.rating) <= 5,\n};\n\nexport function installDemoApi() {\n  const real = window.fetch.bind(window);\n  window.fetch = (input, init = {}) => {\n    const url = typeof input === \"string\" ? input : input.url;\n    if (!url.startsWith(\"/api/\")) return real(input, init);\n    const method = (init.method || \"GET\").toUpperCase();\n    let body = {};\n    try { body = init.body ? JSON.parse(init.body) : {}; } catch { body = {}; }\n    const authed = ((init.headers || {}).Authorization || \"\") === \"Bearer demo-token\";\n\n    // ---- public ----\n    if (url === \"/api/contact\") {\n      return s(body.name, 100) && /^\\S+@\\S+\\.\\S+$/.test(s(body.email, 200)) && s(body.message, 2000)\n        ? reply({ ok: true }) : reply({ error: \"Please fill in your name, a valid email, and a message.\" }, 400);\n    }\n    if (url === \"/api/book\") {\n      if (!s(body.name, 100) || !s(body.address, 300) || !s(body.service, 100)) return reply({ error: \"Please fill in your name, address and service.\" }, 400);\n      db.bookings.push({ id: uid(), createdAt: iso(), type: \"appointment\", status: \"pending\", date: \"\", name: s(body.name, 100), address: s(body.address, 300), service: s(body.service, 100) });\n      persist(); return reply({ ok: true });\n    }\n    if (url === \"/api/reviews\") {\n      if (method === \"GET\") return reply(db.reviews.filter((r) => r.status === \"approved\"));\n      if (!valid.reviews(body)) return reply({ error: \"Please add your name, a rating from 1 to 5, and a comment.\" }, 400);\n      db.reviews.push({ id: uid(), createdAt: iso(), name: s(body.name, 60), rating: Math.round(Number(body.rating)), comment: s(body.comment, 500), status: \"pending\" });\n      persist(); return reply({ ok: true });\n    }\n\n    // ---- admin ----\n    if (url === \"/api/admin/login\") {\n      return body.username === \"admin\" && body.password === \"glossy2026\"\n        ? reply({ token: \"demo-token\" }) : reply({ error: \"Wrong username or password.\" }, 401);\n    }\n    const m = url.match(/^\\/api\\/admin\\/(bookings|receipts|reviews)(?:\\/(.+))?$/);\n    if (!m) return reply({ error: \"Not found.\" }, 404);\n    if (!authed) return reply({ error: \"Please log in.\" }, 401);\n    const [, col, id] = m, list = db[col];\n    if (method === \"GET\") return reply(list);\n    if (method === \"DELETE\") { db[col] = list.filter((x) => x.id !== id); persist(); return reply({ ok: true }); }\n    if (!valid[col](body)) return reply({ error: \"Please fill in the required fields.\" }, 400);\n    if (method === \"POST\") {\n      const item = { ...body, id: uid(), createdAt: iso() };\n      if (col === \"receipts\") item.no = \"GS-\" + String(list.reduce((mx, r) => Math.max(mx, parseInt(String(r.no).slice(3)) || 0), 0) + 1).padStart(4, \"0\");\n      list.push(item); persist(); return reply(item);\n    }\n    const i = list.findIndex((x) => x.id === id);\n    if (i < 0) return reply({ error: \"Not found.\" }, 404);\n    list[i] = { ...list[i], ...body, id: list[i].id }; persist(); return reply(list[i]);\n  };\n}\n",
 "src/index.css": "@tailwind base;\n@tailwind components;\n@tailwind utilities;\n\n@layer base {\n  body { @apply bg-petal font-body text-[1.05rem] leading-relaxed text-berry antialiased; }\n  h1, h2, h3 { @apply font-display; }\n  :focus-visible { @apply outline outline-2 outline-offset-2 outline-rose; }\n}\n\n@layer components {\n  .btn { @apply inline-block rounded-full px-6 py-3 font-medium transition-colors; }\n  .btn-primary { @apply bg-rose text-white hover:bg-berry; }\n  .btn-soft { @apply bg-blush text-berry hover:bg-nude; }\n}\n\n/* One memorable moment: the nails settle in on page load */\n@keyframes settle { from { transform: translateY(14px) rotate(var(--r)); opacity: 0; } to { transform: translateY(0) rotate(var(--r)); opacity: 1; } }\n.nail { animation: settle .7s ease-out both; }\n@media (prefers-reduced-motion: reduce) { .nail { animation: none; } }\n\n/* Home page extras */\n@keyframes twinkle { 0%,100% { opacity: .2; transform: scale(.8); } 50% { opacity: 1; transform: scale(1.15); } }\n.sparkle { animation: twinkle 3s ease-in-out infinite; }\n@keyframes marquee { to { transform: translateX(-50%); } }\n.marquee { animation: marquee 22s linear infinite; }\n@media (prefers-reduced-motion: reduce) { .sparkle, .marquee { animation: none; } }\n\n/* Print only the receipt */\n@media print {\n  body * { visibility: hidden; }\n  .print-area, .print-area * { visibility: visible; }\n  .print-area { position: absolute; left: 0; top: 0; width: 100%; }\n}\n",
 "src/App.jsx": "import { Routes, Route, useLocation } from \"react-router-dom\";\nimport { useEffect } from \"react\";\nimport Layout from \"./components/Layout.jsx\";\nimport Home from \"./pages/Home.jsx\";\nimport About from \"./pages/About.jsx\";\nimport Services from \"./pages/Services.jsx\";\nimport Contact from \"./pages/Contact.jsx\";\nimport Book from \"./pages/Book.jsx\";\nimport Admin from \"./pages/Admin.jsx\";\n\nfunction ScrollToTop() {\n  const { pathname } = useLocation();\n  useEffect(() => {\n    window.scrollTo(0, 0);\n  }, [pathname]);\n  return null;\n}\n\nexport default function App() {\n  return (\n    <Layout>\n      <ScrollToTop />\n      <Routes>\n        <Route path=\"/\" element={<Home />} />\n        <Route path=\"/about\" element={<About />} />\n        <Route path=\"/services\" element={<Services />} />\n        <Route path=\"/contact\" element={<Contact />} />\n        <Route path=\"/book\" element={<Book />} />\n        <Route path=\"/admin\" element={<Admin />} />\n        <Route path=\"*\" element={<Home />} />\n      </Routes>\n    </Layout>\n  );\n}\n",
 "src/main.jsx": "import React from \"react\";\nimport { createRoot } from \"react-dom/client\";\nimport { BrowserRouter } from \"react-router-dom\";\nimport App from \"./App.jsx\";\nimport ErrorBoundary from \"./components/ErrorBoundary.jsx\";\nimport { installDemoApi } from \"./demoApi.js\";\nimport \"./index.css\";\n\nif (import.meta.env.VITE_DEMO === \"true\") installDemoApi();\n\ncreateRoot(document.getElementById(\"root\")).render(\n  <React.StrictMode>\n    <BrowserRouter>\n      <ErrorBoundary><App /></ErrorBoundary>\n    </BrowserRouter>\n  </React.StrictMode>\n);\n\n// Errors outside React (e.g. a script failing to load) also get shown on screen\nwindow.addEventListener(\"error\", (e) => {\n  const root = document.getElementById(\"root\");\n  if (root && !root.children.length) root.textContent = \"Error: \" + e.message;\n});\n",
 "src/data.js": "// Edit your business details, services and prices here.\nexport const business = {\n  name: \"Nails by Glossy Six\",\n  email: \"glossysix06@gmail.com\",\n  address: \"632 Blvd Street, San Agustin, City of San Fernando, Pampanga\",\n  // Used by the map on the Contact page. Edit if the pin is off.\n  mapQuery: \"San Agustin, City of San Fernando, Pampanga, Philippines\",\n  // Replace \"#\" with your real page links\n  socials: [\n    { label: \"Facebook\", href: \"#\" },\n    { label: \"Instagram\", href: \"#\" },\n    { label: \"TikTok\", href: \"#\" },\n  ],\n};\n\nconst img = (n) => `/images/${n}.jpg`;\n\n// Prices come from your Nail Menu poster. A \"+\" means the price starts at that amount.\nexport const categories = [\n  {\n    id: \"gel-extensions\",\n    title: \"Gel Extensions\",\n    tagline: \"Longer nails, more possibilities!\",\n    items: [\n      { name: \"Natural / Plain\", price: \"₱350\", image: img(\"gel-natural\"), desc: \"A clean, glossy set in a soft natural shade.\" },\n      { name: \"Classic French\", price: \"₱400\", image: img(\"gel-french\"), desc: \"Timeless white tips on a sheer, natural base.\" },\n      { name: \"Ombre\", price: \"₱450\", image: img(\"gel-ombre\"), desc: \"A soft, blended fade from one shade to the next.\" },\n      { name: \"Glitter / Chrome\", price: \"₱500\", image: img(\"gel-chrome\"), desc: \"Sparkle or mirror shine for a standout set.\" },\n      { name: \"Custom Design\", price: \"₱550+\", image: img(\"gel-custom\"), desc: \"Your idea, our hands. Tell us the look you want.\" },\n    ],\n  },\n  {\n    id: \"custom-nail-art\",\n    title: \"Custom Nail Art\",\n    tagline: \"Small details, big difference!\",\n    items: [\n      { name: \"Simple Art\", price: \"₱50\", image: img(\"art-simple\"), desc: \"A little accent like a line, dot, or tiny shape.\" },\n      { name: \"Detailed Art\", price: \"₱80\", image: img(\"art-detailed\"), desc: \"Hand-painted patterns with extra detail.\" },\n      { name: \"3D / Charms\", price: \"₱100+\", image: img(\"art-3d\"), desc: \"Raised designs and charms for extra personality.\" },\n      { name: \"Seasonal / Trend Designs\", price: \"₱100+\", image: img(\"art-seasonal\"), desc: \"Fresh looks for the season and what's trending.\" },\n      { name: \"Full Set Design\", price: \"₱150+\", image: img(\"art-fullset\"), desc: \"A matching design across every nail.\" },\n    ],\n  },\n  {\n    id: \"builder-gel-upgrade\",\n    title: \"Builder Gel Upgrade\",\n    tagline: \"Stronger nails, longer lasting!\",\n    items: [\n      { name: \"Builder Gel (Natural)\", price: \"₱150\", image: img(\"builder-natural\"), desc: \"A strengthening layer in a natural finish.\" },\n      { name: \"Builder Gel (With Color)\", price: \"₱180\", image: img(\"builder-color\"), desc: \"Extra strength plus your favorite shade.\" },\n      { name: \"Builder Gel (With Design)\", price: \"₱220+\", image: img(\"builder-design\"), desc: \"Extra strength plus a design of your choice.\" },\n    ],\n  },\n  {\n    // These are listed on your services poster but have no price yet. Add prices here.\n    id: \"more-services\",\n    title: \"More Services\",\n    tagline: \"Everyday care, beautifully done.\",\n    items: [\n      { name: \"Gel Polish\", price: \"Ask us\", image: img(\"more-gel\"), desc: \"Long-lasting shine in your favorite color.\" },\n      { name: \"Manicure & Pedicure\", price: \"Ask us\", image: img(\"more-pedi\"), desc: \"Neat, clean hands and feet with a polished finish.\" },\n      { name: \"Nail Repair\", price: \"Ask us\", image: img(\"more-repair\"), desc: \"Fix for a broken or lifted nail.\" },\n    ],\n  },\n];\n\n// Flat list used by the booking form and admin\nexport const services = categories.flatMap((c) => c.items.map((i) => ({ ...i, category: c.title })));\nexport const logo = img(\"logo\");\nexport const gallery = [\"gel-custom\", \"art-detailed\", \"gel-chrome\", \"art-seasonal\", \"builder-color\", \"art-simple\", \"gel-french\", \"builder-design\"].map(img);\n\n// Sample 5-star reviews. They only fill empty space beside the review form:\n// real (approved) customer reviews replace them automatically. Edit or delete as you like.\nexport const sampleReviews = [\n  { id: \"s1\", name: \"Maria S.\", rating: 5, sample: true, comment: \"So pretty and so affordable! My French tips lasted for weeks.\" },\n  { id: \"s2\", name: \"Jen D.\", rating: 5, sample: true, comment: \"They made my design exactly how I imagined it. Love it!\" },\n  { id: \"s3\", name: \"Kyla R.\", rating: 5, sample: true, comment: \"Friendly girls and a very clean setup. Will book again!\" },\n  { id: \"s4\", name: \"Angel M.\", rating: 5, sample: true, comment: \"My builder gel set is strong, glossy and so cute.\" },\n];\n",
 "src/components/ErrorBoundary.jsx": "import React from \"react\";\n\n// Shows the real error on screen instead of a blank white page.\nexport default class ErrorBoundary extends React.Component {\n  state = { error: null };\n  static getDerivedStateFromError(error) { return { error }; }\n  render() {\n    if (!this.state.error) return this.props.children;\n    return (\n      <div style={{ padding: 24, fontFamily: \"sans-serif\", color: \"#4A2630\" }}>\n        <h1 style={{ fontSize: 22 }}>Oops, something broke</h1>\n        <p>Please send this message to your developer:</p>\n        <pre style={{ whiteSpace: \"pre-wrap\", background: \"#FBE3E8\", padding: 12, borderRadius: 8 }}>\n          {String(this.state.error && (this.state.error.stack || this.state.error.message || this.state.error)).slice(0, 900)}\n        </pre>\n      </div>\n    );\n  }\n}\n",
 "src/components/Layout.jsx": "import { useState } from \"react\";\nimport { NavLink, Link } from \"react-router-dom\";\nimport { business } from \"../data.js\";\n\nconst links = [\n  { to: \"/\", label: \"Home\" },\n  { to: \"/about\", label: \"About\" },\n  { to: \"/services\", label: \"Services\" },\n  { to: \"/contact\", label: \"Contact\" },\n  { to: \"/book\", label: \"Book now\", cta: true },\n];\n\n// \"Book now\" is a colored button; the other links are soft pills\nconst linkClass = ({ isActive }, cta) =>\n  cta\n    ? `rounded-full bg-rose px-5 py-2 text-center font-bold text-white shadow-md shadow-rose/30 transition-colors hover:bg-berry md:ml-2 ${isActive ? \"ring-2 ring-berry/30\" : \"\"}`\n    : `rounded-full px-4 py-2 font-semibold transition-colors ${isActive ? \"bg-blush text-berry\" : \"hover:bg-blush/60\"}`;\n\nexport default function Layout({ children }) {\n  const [open, setOpen] = useState(false);\n\n  return (\n    <div className=\"flex min-h-screen flex-col\">\n      <header className=\"sticky top-0 z-20 border-b border-blush bg-petal/95 backdrop-blur\">\n        <div className=\"mx-auto flex max-w-5xl items-center justify-between px-5 py-3\">\n          <Link to=\"/\" className=\"font-script text-3xl text-rose\">{business.name}</Link>\n          <nav className=\"hidden items-center gap-1 md:flex\" aria-label=\"Main\">\n            {links.map((l) => (\n              <NavLink key={l.to} to={l.to} end className={(s) => linkClass(s, l.cta)}>{l.label}</NavLink>\n            ))}\n          </nav>\n          <button\n            className=\"rounded-full bg-blush px-4 py-2 font-semibold md:hidden\"\n            aria-expanded={open}\n            aria-controls=\"mobile-nav\"\n            onClick={() => setOpen(!open)}\n          >\n            {open ? \"Close\" : \"Menu\"}\n          </button>\n        </div>\n        {open && (\n          <nav id=\"mobile-nav\" className=\"flex flex-col gap-2 px-5 pb-4 md:hidden\" aria-label=\"Mobile\">\n            {links.map((l) => (\n              <NavLink key={l.to} to={l.to} end className={(s) => linkClass(s, l.cta)} onClick={() => setOpen(false)}>\n                {l.label}\n              </NavLink>\n            ))}\n          </nav>\n        )}\n      </header>\n\n      <main className=\"flex-1\">{children}</main>\n\n      <footer className=\"bg-nude/50\">\n        <div className=\"mx-auto grid max-w-5xl gap-6 px-5 py-10 sm:grid-cols-2\">\n          <div>\n            <p className=\"font-script text-3xl text-rose\">{business.name}</p>\n            <p className=\"mt-2 max-w-xs\">Your beauty, your style, your shine. Home service available.</p>\n          </div>\n          <div className=\"space-y-1\">\n            <p><a className=\"underline\" href={`mailto:${business.email}`}>{business.email}</a></p>\n            <p>{business.address}</p>\n            <p className=\"flex gap-4 pt-2\">\n              {business.socials.map((s) => (\n                <a key={s.label} href={s.href} className=\"underline\" target=\"_blank\" rel=\"noreferrer\">{s.label}</a>\n              ))}\n            </p>\n          </div>\n        </div>\n        <p className=\"border-t border-blush py-4 text-center text-sm\">\n          {import.meta.env.VITE_DEMO === \"true\" && <span className=\"mb-1 block\">Demo site: bookings and reviews are saved only in your own browser.</span>}\n          © {new Date().getFullYear()} {business.name} · <Link to=\"/admin\" className=\"underline\">Admin</Link>\n        </p>\n      </footer>\n    </div>\n  );\n}\n",
 "src/components/Reviews.jsx": "import { useEffect, useState } from \"react\";\nimport { sampleReviews } from \"../data.js\";\n\nconst stars = (n) => \"★\".repeat(n) + \"☆\".repeat(5 - n);\nconst field = \"mt-1 w-full rounded-xl border border-nude bg-white px-4 py-3\";\n\nexport default function Reviews() {\n  const [list, setList] = useState(null); // null = still loading\n  const [form, setForm] = useState({ name: \"\", rating: 5, comment: \"\" });\n  const [status, setStatus] = useState({ type: \"idle\", text: \"\" });\n\n  useEffect(() => {\n    fetch(\"/api/reviews\")\n      .then((r) => (r.ok ? r.json() : []))\n      .then(setList)\n      .catch(() => setList([]));\n  }, []);\n\n  const real = (list || []).slice(-6).reverse();\n  // Keep at least 4 cards so there is never an empty gap beside the form\n  const shown = list === null ? [] : [...real, ...sampleReviews.slice(0, Math.max(0, 4 - real.length))];\n  const avg = list && list.length ? (list.reduce((s, r) => s + r.rating, 0) / list.length).toFixed(1) : null;\n\n  async function submit(e) {\n    e.preventDefault();\n    setStatus({ type: \"loading\", text: \"Sending...\" });\n    try {\n      const res = await fetch(\"/api/reviews\", { method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: JSON.stringify(form) });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || \"Something went wrong.\");\n      setForm({ name: \"\", rating: 5, comment: \"\" });\n      setStatus({ type: \"ok\", text: \"Thank you! Your review will show here once we approve it.\" });\n    } catch (err) {\n      setStatus({ type: \"error\", text: err.message });\n    }\n  }\n\n  return (\n    <section className=\"mx-auto max-w-5xl px-5 py-16\">\n      <h2 className=\"text-3xl font-bold sm:text-4xl\">What our customers say</h2>\n      <p className=\"font-script text-2xl text-rose\">\n        {avg ? `${avg} out of 5, from ${list.length} review${list.length > 1 ? \"s\" : \"\"}` : \"Be the first to leave a review!\"}\n      </p>\n\n      <div className=\"mt-8 grid gap-8 md:grid-cols-[3fr_2fr]\">\n        <div className=\"grid auto-rows-fr gap-4 sm:grid-cols-2\">\n          {list === null && <p>Loading reviews...</p>}\n          {shown.map((r) => (\n            <figure key={r.id} className=\"flex flex-col justify-between rounded-3xl border border-blush bg-white p-5 shadow-sm\">\n              <p className=\"text-lg text-gold\" role=\"img\" aria-label={`${r.rating} out of 5 stars`}>{stars(r.rating)}</p>\n              <blockquote className=\"mt-2 font-display italic\">“{r.comment}”</blockquote>\n              <figcaption className=\"mt-3 font-bold\">{r.name}{r.sample && <span className=\"ml-2 text-xs font-normal opacity-70\">sample review</span>}</figcaption>\n            </figure>\n          ))}\n        </div>\n\n        <form onSubmit={submit} className=\"flex flex-col gap-4 rounded-3xl bg-blush/50 p-6\">\n          <h3 className=\"text-xl font-bold\">Leave a review</h3>\n          <label className=\"block\">Your name\n            <input className={field} required maxLength={60} value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />\n          </label>\n          <fieldset>\n            <legend>Your rating</legend>\n            <div className=\"mt-1 flex gap-1\">\n              {[1, 2, 3, 4, 5].map((n) => (\n                <button key={n} type=\"button\" aria-label={`${n} star${n > 1 ? \"s\" : \"\"}`} aria-pressed={form.rating === n}\n                  onClick={() => setForm({ ...form, rating: n })}\n                  className={`text-3xl leading-none ${n <= form.rating ? \"text-gold\" : \"text-nude\"}`}>★</button>\n              ))}\n            </div>\n          </fieldset>\n          <label className=\"flex flex-1 flex-col\">Your review\n            <textarea className={`${field} min-h-[6rem] flex-1`} required maxLength={500} value={form.comment} onChange={(e) => setForm({ ...form, comment: e.target.value })} />\n          </label>\n          <button className=\"btn btn-primary w-full disabled:opacity-60\" disabled={status.type === \"loading\"}>Send review</button>\n          {status.text && <p role=\"status\" className={status.type === \"error\" ? \"text-red-700\" : \"\"}>{status.text}</p>}\n        </form>\n      </div>\n    </section>\n  );\n}\n",
 "src/components/NailRow.jsx": "// A row of glossy nails drawn with CSS only.\nconst nails = [\n  { bg: \"linear-gradient(160deg,#F9DDE2,#EFA9B8)\", h: \"h-24\", r: \"-6deg\", d: \"0s\" },\n  { bg: \"linear-gradient(160deg,#F3DCCF,#DDB8A5)\", h: \"h-28\", r: \"-2deg\", d: \".08s\" },\n  { bg: \"linear-gradient(160deg,#FFFFFF,#F2E6E2)\", h: \"h-32\", r: \"0deg\",  d: \".16s\" },\n  { bg: \"linear-gradient(160deg,#F6C3CE,#D9758C)\", h: \"h-28\", r: \"3deg\",  d: \".24s\" },\n  { bg: \"linear-gradient(160deg,#EBD3C6,#CFA692)\", h: \"h-24\", r: \"7deg\",  d: \".32s\" },\n];\n\nexport default function NailRow() {\n  return (\n    <div className=\"flex items-end justify-center gap-3\" aria-hidden=\"true\">\n      {nails.map((n, i) => (\n        <div\n          key={i}\n          className={`nail relative w-14 sm:w-16 ${n.h} rounded-t-[2rem] rounded-b-xl shadow-md`}\n          style={{ background: n.bg, \"--r\": n.r, animationDelay: n.d }}\n        >\n          <span className=\"absolute left-2 top-3 h-1/2 w-2 rounded-full bg-white/70\" />\n        </div>\n      ))}\n    </div>\n  );\n}\n",
 "src/pages/Book.jsx": "import { useState } from \"react\";\nimport { useSearchParams } from \"react-router-dom\";\nimport { categories, services } from \"../data.js\";\n\nconst field = \"mt-1 w-full rounded-xl border border-nude bg-white px-4 py-3\";\n\nexport default function Book() {\n  const [params] = useSearchParams();\n  const first = params.get(\"service\");\n  const [form, setForm] = useState({\n    name: \"\", address: \"\",\n    service: services.some((s) => s.name === first) ? first : services[0].name,\n  });\n  const [status, setStatus] = useState({ type: \"idle\", text: \"\" });\n  const set = (k) => (e) => setForm({ ...form, [k]: e.target.value });\n\n  async function submit(e) {\n    e.preventDefault();\n    setStatus({ type: \"loading\", text: \"Sending...\" });\n    try {\n      const res = await fetch(\"/api/book\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify(form),\n      });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || \"Something went wrong.\");\n      setForm({ ...form, name: \"\", address: \"\" });\n      setStatus({ type: \"ok\", text: \"Booking received! We'll message you to confirm your slot.\" });\n    } catch (err) {\n      setStatus({ type: \"error\", text: err.message });\n    }\n  }\n\n  return (\n    <div className=\"mx-auto max-w-xl px-5 py-14\">\n      <h1 className=\"text-4xl font-bold sm:text-5xl\">Book a slot</h1>\n      <p className=\"mt-3\">Fill this in and we'll confirm with you.</p>\n      <form onSubmit={submit} className=\"mt-8 space-y-4 rounded-3xl bg-blush/50 p-6 sm:p-8\">\n        <label className=\"block\">Name\n          <input className={field} required value={form.name} onChange={set(\"name\")} autoComplete=\"name\" />\n        </label>\n        <label className=\"block\">Address\n          <input className={field} required value={form.address} onChange={set(\"address\")} autoComplete=\"street-address\" />\n        </label>\n        <label className=\"block\">Name of service\n          <select className={field} value={form.service} onChange={set(\"service\")}>\n            {categories.map((c) => <optgroup key={c.title} label={c.title}>{c.items.map((s) => <option key={s.name}>{s.name}</option>)}</optgroup>)}\n          </select>\n        </label>\n        <button className=\"btn btn-primary w-full disabled:opacity-60\" disabled={status.type === \"loading\"}>\n          Send booking\n        </button>\n        {status.text && <p role=\"status\" className={status.type === \"error\" ? \"text-red-700\" : \"\"}>{status.text}</p>}\n      </form>\n    </div>\n  );\n}\n",
 "src/pages/Services.jsx": "import { Link } from \"react-router-dom\";\nimport { categories } from \"../data.js\";\n\nconst go = (id) => { const el = document.getElementById(id); if (el) el.scrollIntoView({ behavior: \"smooth\", block: \"start\" }); };\nconst priceLabel = (p) => (p.startsWith(\"₱\") ? p : \"Ask for price\");\n\nexport default function Services() {\n  return (\n    <div className=\"mx-auto max-w-5xl px-5 py-14\">\n      <h1 className=\"text-4xl font-bold sm:text-5xl\">Services</h1>\n      <p className=\"mt-3 max-w-xl text-lg\">Pick a category, choose your style, and tap Book. A \"+\" means the price starts at that amount. You can also request your own design.</p>\n      <div className=\"mt-6 flex flex-wrap gap-2\">\n        {categories.map((c) => (\n          <button key={c.id} onClick={() => go(c.id)} className=\"rounded-full bg-blush px-4 py-2 font-semibold hover:bg-nude\">{c.title}</button>\n        ))}\n      </div>\n\n      {categories.map((c, ci) => (\n        <section key={c.id} id={c.id} className={`mt-12 scroll-mt-24 rounded-[2rem] p-5 sm:p-8 ${ci % 2 ? \"bg-nude/40\" : \"bg-blush/40\"}`}>\n          <h2 className=\"text-3xl font-bold\">{c.title}</h2>\n          <p className=\"font-script text-2xl text-rose\">{c.tagline}</p>\n          <div className=\"mt-6 grid gap-5 sm:grid-cols-2 lg:grid-cols-3\">\n            {c.items.map((s) => (\n              <article key={s.name} className=\"flex flex-col overflow-hidden rounded-3xl border border-blush bg-white shadow-sm\">\n                <img src={s.image} alt={`${s.name} nail example`} loading=\"lazy\" className=\"aspect-square w-full object-cover\" />\n                <div className=\"flex flex-1 flex-col p-5\">\n                  <h3 className=\"text-xl font-bold\">{s.name}</h3>\n                  <p className=\"mt-1 flex-1\">{s.desc}</p>\n                  <div className=\"mt-4 flex items-center justify-between gap-3\">\n                    <span className=\"rounded-full bg-nude px-4 py-1 font-bold\">{priceLabel(s.price)}</span>\n                    <Link to={`/book?service=${encodeURIComponent(s.name)}`} className=\"btn btn-primary px-5 py-2\">Book</Link>\n                  </div>\n                </div>\n              </article>\n            ))}\n            {c.items.length % 3 === 2 && (\n              <article className=\"flex flex-col justify-center rounded-3xl bg-rose p-6 text-white\">\n                <p className=\"font-script text-3xl\">Have your own idea?</p>\n                <p className=\"mt-2\">You can request your own nail design. We'll do our best to make it happen!</p>\n                <Link to=\"/contact\" className=\"btn mt-4 self-start bg-white px-5 py-2 text-rose hover:bg-blush\">Message us</Link>\n              </article>\n            )}\n          </div>\n        </section>\n      ))}\n    </div>\n  );\n}\n",
 "src/pages/Contact.jsx": "import { useState } from \"react\";\nimport { business } from \"../data.js\";\n\nconst field = \"mt-1 w-full rounded-xl border border-nude bg-white px-4 py-3\";\n\nexport default function Contact() {\n  const [form, setForm] = useState({ name: \"\", email: \"\", message: \"\" });\n  const [status, setStatus] = useState({ type: \"idle\", text: \"\" });\n  const set = (k) => (e) => setForm({ ...form, [k]: e.target.value });\n\n  async function submit(e) {\n    e.preventDefault();\n    setStatus({ type: \"loading\", text: \"Sending...\" });\n    try {\n      const res = await fetch(\"/api/contact\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify(form),\n      });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || \"Something went wrong.\");\n      setForm({ name: \"\", email: \"\", message: \"\" });\n      setStatus({ type: \"ok\", text: \"Message sent! We'll reply soon.\" });\n    } catch (err) {\n      setStatus({ type: \"error\", text: err.message });\n    }\n  }\n\n  return (\n    <div className=\"mx-auto grid max-w-5xl gap-8 px-5 py-14 md:grid-cols-2\">\n      {/* Left: details + map (the map grows so both columns end at the same line) */}\n      <div className=\"flex flex-col\">\n        <h1 className=\"text-4xl font-bold sm:text-5xl\">Contact</h1>\n        <p className=\"mt-3 max-w-sm text-lg\">Tell us the design you want and when you're free. We'll confirm your slot.</p>\n        <dl className=\"mt-6 space-y-4\">\n          <div>\n            <dt className=\"font-script text-2xl text-rose\">Email</dt>\n            <dd><a className=\"underline\" href={`mailto:${business.email}`}>{business.email}</a></dd>\n          </div>\n          <div>\n            <dt className=\"font-script text-2xl text-rose\">Location</dt>\n            <dd>{business.address}</dd>\n          </div>\n          <div>\n            <dt className=\"font-script text-2xl text-rose\">Find us on</dt>\n            <dd className=\"flex gap-4\">\n              {business.socials.map((s) => (\n                <a key={s.label} href={s.href} className=\"underline\" target=\"_blank\" rel=\"noreferrer\">{s.label}</a>\n              ))}\n            </dd>\n          </div>\n        </dl>\n        <div className=\"relative mt-6 min-h-[16rem] flex-1 overflow-hidden rounded-3xl bg-nude/60\">\n          <div className=\"absolute inset-0 flex flex-col items-center justify-center p-6 text-center\">\n            <p className=\"font-script text-3xl text-rose\">Find us here</p>\n            <p className=\"mt-1\">{business.address}</p>\n            <a className=\"btn btn-primary mt-4 px-5 py-2\" target=\"_blank\" rel=\"noreferrer\"\n              href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(business.mapQuery)}`}>Open in Google Maps</a>\n          </div>\n          <iframe\n            title=\"Map of our location\"\n            className=\"absolute inset-0 h-full w-full border-0\"\n            loading=\"lazy\"\n            src={`https://maps.google.com/maps?q=${encodeURIComponent(business.mapQuery)}&output=embed`}\n          />\n        </div>\n      </div>\n\n      {/* Right: form fills the space, plus a home service card */}\n      <div className=\"flex flex-col gap-6\">\n        <form onSubmit={submit} className=\"flex flex-1 flex-col gap-4 rounded-3xl bg-blush/50 p-6 sm:p-8\">\n          <label className=\"block\">Name\n            <input className={field} required value={form.name} onChange={set(\"name\")} autoComplete=\"name\" />\n          </label>\n          <label className=\"block\">Email\n            <input className={field} type=\"email\" required value={form.email} onChange={set(\"email\")} autoComplete=\"email\" />\n          </label>\n          <label className=\"flex flex-1 flex-col\">Message\n            <textarea className={`${field} min-h-[8rem] flex-1`} required value={form.message} onChange={set(\"message\")} />\n          </label>\n          <button className=\"btn btn-primary w-full disabled:opacity-60\" disabled={status.type === \"loading\"}>\n            Send message\n          </button>\n          {status.text && <p role=\"status\" className={status.type === \"error\" ? \"text-red-700\" : \"\"}>{status.text}</p>}\n        </form>\n        <div className=\"rounded-3xl bg-rose p-6 text-white\">\n          <p className=\"font-script text-3xl\">Home service available</p>\n          <p className=\"mt-1\">We bring your nail glow to you! Message us to book your appointment.</p>\n        </div>\n      </div>\n    </div>\n  );\n}\n",
 "src/pages/Admin.jsx": "import { useCallback, useEffect, useMemo, useState } from \"react\";\nimport { business, categories, services } from \"../data.js\";\n\nconst KEY = \"gs_admin_token\";\nconst getTok = () => { try { return sessionStorage.getItem(KEY) || \"\"; } catch { return \"\"; } };\nconst setTok = (t) => { try { t ? sessionStorage.setItem(KEY, t) : sessionStorage.removeItem(KEY); } catch { /* ignore */ } };\nconst peso = (n) => `₱${Number(n || 0).toLocaleString()}`;\nconst priceOf = (name) => Number(((services.find((s) => s.name === name) || {}).price || \"\").replace(/[^\\d.]/g, \"\")) || 0;\nconst today = () => new Date().toISOString().slice(0, 10);\nconst field = \"mt-1 w-full rounded-xl border border-nude bg-white px-3 py-2\";\nconst small = \"rounded-full bg-blush px-3 py-1 text-sm hover:bg-nude\";\nconst statuses = [\"pending\", \"confirmed\", \"done\", \"cancelled\"];\n\n// Grouped service dropdown; keeps an older/unknown service name selectable\nconst Options = ({ extra }) => (\n  <>\n    {categories.map((c) => <optgroup key={c.title} label={c.title}>{c.items.map((s) => <option key={s.name}>{s.name}</option>)}</optgroup>)}\n    {extra && !services.some((s) => s.name === extra) && <option>{extra}</option>}\n  </>\n);\n\nfunction Modal({ children, onClose, error }) {\n  return (\n    <div className=\"fixed inset-0 z-30 overflow-y-auto bg-berry/40 p-4\" onClick={onClose}>\n      <div className=\"mx-auto my-6 w-full max-w-md rounded-3xl bg-petal p-6 shadow-xl\" onClick={(e) => e.stopPropagation()}>\n        {error && <p className=\"mb-3 text-red-700\">{error}</p>}\n        {children}\n      </div>\n    </div>\n  );\n}\n\nfunction Login({ onLogin }) {\n  const [f, setF] = useState({ username: \"\", password: \"\" });\n  const [err, setErr] = useState(\"\");\n  async function submit(e) {\n    e.preventDefault();\n    try {\n      const r = await fetch(\"/api/admin/login\", { method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: JSON.stringify(f) });\n      const d = await r.json();\n      if (!r.ok) throw new Error(d.error || \"Login failed.\");\n      onLogin(d.token);\n    } catch (x) { setErr(x.message); }\n  }\n  return (\n    <div className=\"mx-auto max-w-sm px-5 py-16\">\n      <h1 className=\"text-3xl font-bold\">Admin login</h1>\n      <form onSubmit={submit} className=\"mt-6 space-y-4 rounded-3xl bg-blush/50 p-6\">\n        <label className=\"block\">Username\n          <input className={field} value={f.username} onChange={(e) => setF({ ...f, username: e.target.value })} autoComplete=\"username\" required />\n        </label>\n        <label className=\"block\">Password\n          <input className={field} type=\"password\" value={f.password} onChange={(e) => setF({ ...f, password: e.target.value })} autoComplete=\"current-password\" required />\n        </label>\n        {import.meta.env.VITE_DEMO === \"true\" && <p className=\"text-sm\">Demo login: <b>admin</b> / <b>glossy2026</b></p>}\n        <button className=\"btn btn-primary w-full\">Log in</button>\n        {err && <p role=\"alert\" className=\"text-red-700\">{err}</p>}\n      </form>\n    </div>\n  );\n}\n\nfunction BookingForm({ initial, onSave, onClose }) {\n  const [f, setF] = useState({ name: \"\", address: \"\", service: services[0].name, type: \"walk-in\", status: \"confirmed\", date: today(), ...initial });\n  const set = (k) => (e) => setF({ ...f, [k]: e.target.value });\n  return (\n    <form onSubmit={(e) => { e.preventDefault(); onSave(f); }} className=\"space-y-3\">\n      <h2 className=\"text-2xl font-bold\">{initial.id ? \"Edit booking\" : \"Add booking\"}</h2>\n      <label className=\"block\">Name<input className={field} required value={f.name} onChange={set(\"name\")} /></label>\n      <label className=\"block\">Address<input className={field} value={f.address} onChange={set(\"address\")} /></label>\n      <label className=\"block\">Service\n        <select className={field} value={f.service} onChange={set(\"service\")}><Options /></select>\n      </label>\n      <div className=\"grid grid-cols-2 gap-3\">\n        <label className=\"block\">Type\n          <select className={field} value={f.type} onChange={set(\"type\")}><option value=\"walk-in\">walk-in</option><option value=\"appointment\">appointment</option></select>\n        </label>\n        <label className=\"block\">Status\n          <select className={field} value={f.status} onChange={set(\"status\")}>{statuses.map((s) => <option key={s}>{s}</option>)}</select>\n        </label>\n      </div>\n      <label className=\"block\">Date<input className={field} type=\"date\" value={f.date} onChange={set(\"date\")} /></label>\n      <div className=\"flex gap-2 pt-2\"><button className=\"btn btn-primary\">Save</button><button type=\"button\" className=\"btn btn-soft\" onClick={onClose}>Cancel</button></div>\n    </form>\n  );\n}\n\nfunction ReceiptForm({ initial, onSave, onClose }) {\n  const [f, setF] = useState({ bookingId: \"\", clientName: \"\", service: services[0].name, amount: priceOf(services[0].name), method: \"Cash\", notes: \"\", date: today(), ...initial });\n  const set = (k) => (e) => setF({ ...f, [k]: e.target.value });\n  return (\n    <form onSubmit={(e) => { e.preventDefault(); onSave({ ...f, amount: Number(f.amount) }); }} className=\"space-y-3\">\n      <h2 className=\"text-2xl font-bold\">{initial.id ? \"Edit receipt\" : \"New receipt\"}</h2>\n      <label className=\"block\">Client name<input className={field} required value={f.clientName} onChange={set(\"clientName\")} /></label>\n      <label className=\"block\">Service\n        <select className={field} value={f.service} onChange={(e) => setF({ ...f, service: e.target.value, amount: initial.id ? f.amount : priceOf(e.target.value) })}>\n          <Options extra={f.service} />\n        </select>\n      </label>\n      <div className=\"grid grid-cols-2 gap-3\">\n        <label className=\"block\">Amount (₱)<input className={field} type=\"number\" min=\"0\" step=\"any\" required value={f.amount} onChange={set(\"amount\")} /></label>\n        <label className=\"block\">Payment\n          <select className={field} value={f.method} onChange={set(\"method\")}><option>Cash</option><option>GCash</option><option>Other</option></select>\n        </label>\n      </div>\n      <label className=\"block\">Date<input className={field} type=\"date\" value={f.date} onChange={set(\"date\")} /></label>\n      <label className=\"block\">Notes<input className={field} value={f.notes} onChange={set(\"notes\")} /></label>\n      <div className=\"flex gap-2 pt-2\"><button className=\"btn btn-primary\">Save</button><button type=\"button\" className=\"btn btn-soft\" onClick={onClose}>Cancel</button></div>\n    </form>\n  );\n}\n\nfunction ReviewForm({ initial, onSave, onClose }) {\n  const [f, setF] = useState({ name: \"\", rating: 5, comment: \"\", status: \"approved\", ...initial });\n  const set = (k) => (e) => setF({ ...f, [k]: e.target.value });\n  return (\n    <form onSubmit={(e) => { e.preventDefault(); onSave({ ...f, rating: Number(f.rating) }); }} className=\"space-y-3\">\n      <h2 className=\"text-2xl font-bold\">{initial.id ? \"Edit review\" : \"Add review\"}</h2>\n      <label className=\"block\">Customer name<input className={field} required value={f.name} onChange={set(\"name\")} /></label>\n      <div className=\"grid grid-cols-2 gap-3\">\n        <label className=\"block\">Rating\n          <select className={field} value={f.rating} onChange={set(\"rating\")}>{[5, 4, 3, 2, 1].map((n) => <option key={n} value={n}>{n} stars</option>)}</select>\n        </label>\n        <label className=\"block\">Status\n          <select className={field} value={f.status} onChange={set(\"status\")}>{[\"pending\", \"approved\", \"hidden\"].map((x) => <option key={x}>{x}</option>)}</select>\n        </label>\n      </div>\n      <label className=\"block\">Review<textarea className={field} rows=\"4\" required maxLength={500} value={f.comment} onChange={set(\"comment\")} /></label>\n      <div className=\"flex gap-2 pt-2\"><button className=\"btn btn-primary\">Save</button><button type=\"button\" className=\"btn btn-soft\" onClick={onClose}>Cancel</button></div>\n    </form>\n  );\n}\n\nfunction ReceiptView({ r, onClose }) {\n  return (\n    <>\n      <div className=\"print-area text-center\">\n        <p className=\"font-display text-2xl font-bold italic text-rose\">{business.name}</p>\n        <p className=\"text-sm\">{business.address}</p>\n        <p className=\"text-sm\">{business.email}</p>\n        <hr className=\"my-4 border-nude\" />\n        <p className=\"font-bold\">Receipt {r.no}</p>\n        <p className=\"text-sm\">{r.date || (r.createdAt || \"\").slice(0, 10)}</p>\n        <dl className=\"mt-4 space-y-1 text-left\">\n          <div className=\"flex justify-between\"><dt>Client</dt><dd>{r.clientName}</dd></div>\n          <div className=\"flex justify-between\"><dt>Service</dt><dd>{r.service}</dd></div>\n          <div className=\"flex justify-between\"><dt>Payment</dt><dd>{r.method}</dd></div>\n          {r.notes && <div className=\"flex justify-between\"><dt>Notes</dt><dd>{r.notes}</dd></div>}\n          <div className=\"flex justify-between border-t border-nude pt-2 text-lg font-bold\"><dt>Total</dt><dd>{peso(r.amount)}</dd></div>\n        </dl>\n        <p className=\"mt-5 font-display italic\">Thank you! See you again.</p>\n      </div>\n      <div className=\"mt-5 flex gap-2\"><button className=\"btn btn-primary\" onClick={() => window.print()}>Print</button><button className=\"btn btn-soft\" onClick={onClose}>Close</button></div>\n    </>\n  );\n}\n\nexport default function Admin() {\n  const [token, setToken] = useState(getTok());\n  const [tab, setTab] = useState(\"dashboard\");\n  const [bookings, setBookings] = useState([]);\n  const [receipts, setReceipts] = useState([]);\n  const [reviews, setReviews] = useState([]);\n  const [modal, setModal] = useState(null);\n  const [error, setError] = useState(\"\");\n\n  const call = useCallback(async (method, url, body) => {\n    const r = await fetch(url, { method, headers: { \"Content-Type\": \"application/json\", Authorization: `Bearer ${token}` }, body: body ? JSON.stringify(body) : undefined });\n    const d = await r.json().catch(() => ({}));\n    if (r.status === 401) { setTok(\"\"); setToken(\"\"); }\n    if (!r.ok) throw new Error(d.error || \"Something went wrong.\");\n    return d;\n  }, [token]);\n\n  const load = useCallback(async () => {\n    try {\n      const [b, r, v] = await Promise.all([call(\"GET\", \"/api/admin/bookings\"), call(\"GET\", \"/api/admin/receipts\"), call(\"GET\", \"/api/admin/reviews\")]);\n      setBookings(b); setReceipts(r); setReviews(v); setError(\"\");\n    } catch (e) { setError(e.message); }\n  }, [call]);\n  useEffect(() => { if (token) load(); }, [token, load]);\n\n  const stats = useMemo(() => {\n    const active = bookings.filter((b) => b.status !== \"cancelled\");\n    const per = {};\n    services.forEach((s) => { per[s.name] = 0; });\n    active.forEach((b) => { per[b.service] = (per[b.service] || 0) + 1; });\n    return {\n      walkIn: active.filter((b) => b.type === \"walk-in\").length,\n      appt: active.filter((b) => b.type === \"appointment\").length,\n      pending: bookings.filter((b) => b.status === \"pending\").length,\n      revenue: receipts.reduce((s, r) => s + Number(r.amount || 0), 0),\n      per,\n    };\n  }, [bookings, receipts]);\n\n  if (!token) return <Login onLogin={(t) => { setTok(t); setToken(t); }} />;\n\n  const run = async (fn) => { try { await fn(); setModal(null); setError(\"\"); } catch (e) { setError(e.message); } };\n  const url = (col, id) => `/api/admin/${col}${id ? `/${id}` : \"\"}`;\n  const saveBooking = (data) => run(async () => { await call(data.id ? \"PUT\" : \"POST\", url(\"bookings\", data.id), data); await load(); });\n  const saveReceipt = (data) => run(async () => {\n    await call(data.id ? \"PUT\" : \"POST\", url(\"receipts\", data.id), data);\n    const b = bookings.find((x) => x.id === data.bookingId);\n    if (!data.id && b && b.status !== \"done\") await call(\"PUT\", url(\"bookings\", b.id), { ...b, status: \"done\" });\n    await load();\n  });\n  const remove = (col, id) => { if (window.confirm(\"Delete this? This cannot be undone.\")) run(async () => { await call(\"DELETE\", url(col, id)); await load(); }); };\n  const setStatus = (b, status) => run(async () => { await call(\"PUT\", url(\"bookings\", b.id), { ...b, status }); await load(); });\n  const logout = () => { setTok(\"\"); setToken(\"\"); };\n  const saveReview = (data) => run(async () => { await call(data.id ? \"PUT\" : \"POST\", url(\"reviews\", data.id), data); await load(); });\n  const setReviewStatus = (r, status) => run(async () => { await call(\"PUT\", url(\"reviews\", r.id), { ...r, status }); await load(); });\n\n  const pendingReviews = reviews.filter((r) => r.status === \"pending\").length;\n  const max = Math.max(1, ...Object.values(stats.per));\n  const tiles = [[\"Walk-in\", stats.walkIn], [\"Appointments\", stats.appt], [\"Pending\", stats.pending], [\"Revenue\", peso(stats.revenue)]];\n\n  return (\n    <div className=\"mx-auto max-w-5xl px-5 py-10\">\n      <div className=\"flex flex-wrap items-center justify-between gap-3\">\n        <h1 className=\"text-3xl font-bold\">Admin</h1>\n        <nav className=\"flex flex-wrap gap-2\" aria-label=\"Admin\">\n          {[\"dashboard\", \"bookings\", \"receipts\", \"reviews\"].map((t) => (\n            <button key={t} onClick={() => setTab(t)} className={`rounded-full px-4 py-2 capitalize ${tab === t ? \"bg-rose text-white\" : \"bg-blush\"}`}>{t === \"reviews\" && pendingReviews ? `reviews (${pendingReviews} new)` : t}</button>\n          ))}\n          <button onClick={logout} className=\"rounded-full px-4 py-2 underline\">Log out</button>\n        </nav>\n      </div>\n      {error && <p role=\"alert\" className=\"mt-4 text-red-700\">{error}</p>}\n\n      {tab === \"dashboard\" && (\n        <>\n          <div className=\"mt-6 grid grid-cols-2 gap-4 md:grid-cols-4\">\n            {tiles.map(([l, v]) => (\n              <div key={l} className=\"rounded-3xl bg-blush/60 p-5\"><p className=\"text-sm\">{l}</p><p className=\"font-display text-3xl font-bold\">{v}</p></div>\n            ))}\n          </div>\n          <h2 className=\"mt-10 text-2xl font-bold\">Bookings per service</h2>\n          {[...categories.map((c) => [c.title, c.items.map((x) => x.name)]), [\"Other / older services\", Object.keys(stats.per).filter((n) => !services.some((x) => x.name === n))]]\n            .filter(([, names]) => names.length)\n            .map(([title, names]) => (\n              <div key={title} className=\"mt-6\">\n                <h3 className=\"font-display text-lg font-bold text-rose\">{title}</h3>\n                <ul className=\"mt-2 space-y-3\">\n                  {names.map((name) => (\n                    <li key={name}>\n                      <div className=\"flex justify-between\"><span>{name}</span><span className=\"font-bold\">{stats.per[name] || 0}</span></div>\n                      <div className=\"mt-1 h-3 rounded-full bg-nude/60\"><div className=\"h-3 rounded-full bg-rose\" style={{ width: `${((stats.per[name] || 0) / max) * 100}%` }} /></div>\n                    </li>\n                  ))}\n                </ul>\n              </div>\n            ))}\n          <p className=\"mt-6 text-sm\">Cancelled bookings are not counted. Revenue is the total of all receipts ({receipts.length}).</p>\n        </>\n      )}\n\n      {tab === \"bookings\" && (\n        <>\n          <button className=\"btn btn-primary mt-6\" onClick={() => setModal({ kind: \"booking\", item: {} })}>Add booking / walk-in</button>\n          <div className=\"mt-4 divide-y divide-blush rounded-3xl bg-white\">\n            {bookings.length === 0 && <p className=\"p-5\">No bookings yet.</p>}\n            {[...bookings].reverse().map((b) => (\n              <div key={b.id} className=\"flex flex-wrap items-center gap-3 p-4\">\n                <div className=\"min-w-[10rem] flex-1\">\n                  <p className=\"font-bold\">{b.name}</p>\n                  <p className=\"text-sm\">{b.address || \"No address\"}</p>\n                  <p className=\"text-sm\">{b.service} · {b.date || (b.createdAt || \"\").slice(0, 10)}</p>\n                </div>\n                <span className=\"rounded-full bg-nude px-3 py-1 text-sm\">{b.type}</span>\n                <select aria-label=\"Status\" className=\"rounded-xl border border-nude bg-white px-2 py-1\" value={b.status} onChange={(e) => setStatus(b, e.target.value)}>\n                  {statuses.map((s) => <option key={s}>{s}</option>)}\n                </select>\n                <button className={small} onClick={() => setModal({ kind: \"receipt\", item: { bookingId: b.id, clientName: b.name, service: b.service, amount: priceOf(b.service) } })}>Receipt</button>\n                <button className={small} onClick={() => setModal({ kind: \"booking\", item: b })}>Edit</button>\n                <button className={small} onClick={() => remove(\"bookings\", b.id)}>Delete</button>\n              </div>\n            ))}\n          </div>\n        </>\n      )}\n\n      {tab === \"receipts\" && (\n        <>\n          <button className=\"btn btn-primary mt-6\" onClick={() => setModal({ kind: \"receipt\", item: {} })}>New receipt</button>\n          <div className=\"mt-4 divide-y divide-blush rounded-3xl bg-white\">\n            {receipts.length === 0 && <p className=\"p-5\">No receipts yet.</p>}\n            {[...receipts].reverse().map((r) => (\n              <div key={r.id} className=\"flex flex-wrap items-center gap-3 p-4\">\n                <div className=\"min-w-[10rem] flex-1\">\n                  <p className=\"font-bold\">{r.no} · {r.clientName}</p>\n                  <p className=\"text-sm\">{r.service} · {r.method} · {r.date || (r.createdAt || \"\").slice(0, 10)}</p>\n                </div>\n                <p className=\"font-display text-lg font-bold\">{peso(r.amount)}</p>\n                <button className={small} onClick={() => setModal({ kind: \"view\", item: r })}>View / Print</button>\n                <button className={small} onClick={() => setModal({ kind: \"receipt\", item: r })}>Edit</button>\n                <button className={small} onClick={() => remove(\"receipts\", r.id)}>Delete</button>\n              </div>\n            ))}\n          </div>\n        </>\n      )}\n\n      {tab === \"reviews\" && (\n        <>\n          <button className=\"btn btn-primary mt-6\" onClick={() => setModal({ kind: \"review\", item: {} })}>Add review</button>\n          <p className=\"mt-3 text-sm\">New customer reviews start as \"pending\". Set one to \"approved\" to show it on the About page. \"hidden\" removes it from the page without deleting it.</p>\n          <div className=\"mt-4 divide-y divide-blush rounded-3xl bg-white\">\n            {reviews.length === 0 && <p className=\"p-5\">No reviews yet.</p>}\n            {[...reviews].reverse().map((r) => (\n              <div key={r.id} className=\"flex flex-wrap items-center gap-3 p-4\">\n                <div className=\"min-w-[10rem] flex-1\">\n                  <p className=\"font-bold\">{r.name} <span className=\"text-gold\" aria-label={`${r.rating} stars`}>{\"★\".repeat(r.rating)}{\"☆\".repeat(5 - r.rating)}</span></p>\n                  <p className=\"text-sm\">{r.comment}</p>\n                </div>\n                <select aria-label=\"Review status\" className=\"rounded-xl border border-nude bg-white px-2 py-1\" value={r.status} onChange={(e) => setReviewStatus(r, e.target.value)}>\n                  {[\"pending\", \"approved\", \"hidden\"].map((x) => <option key={x}>{x}</option>)}\n                </select>\n                <button className={small} onClick={() => setModal({ kind: \"review\", item: r })}>Edit</button>\n                <button className={small} onClick={() => remove(\"reviews\", r.id)}>Delete</button>\n              </div>\n            ))}\n          </div>\n        </>\n      )}\n\n      {modal && (\n        <Modal onClose={() => setModal(null)} error={error}>\n          {modal.kind === \"booking\" && <BookingForm initial={modal.item} onSave={saveBooking} onClose={() => setModal(null)} />}\n          {modal.kind === \"receipt\" && <ReceiptForm initial={modal.item} onSave={saveReceipt} onClose={() => setModal(null)} />}\n          {modal.kind === \"review\" && <ReviewForm initial={modal.item} onSave={saveReview} onClose={() => setModal(null)} />}\n          {modal.kind === \"view\" && <ReceiptView r={modal.item} onClose={() => setModal(null)} />}\n        </Modal>\n      )}\n    </div>\n  );\n}\n",
 "src/pages/About.jsx": "import { Link } from \"react-router-dom\";\nimport { logo, gallery } from \"../data.js\";\nimport Reviews from \"../components/Reviews.jsx\";\n\nconst values = [\n  [\"Creativity\", \"Every set is a chance to try something new and make it yours.\"],\n  [\"Affordability\", \"Pretty nails should never cost too much.\"],\n  [\"Confidence\", \"We want you to leave feeling happy and proud of your nails.\"],\n  [\"Friendliness\", \"We reply, we listen, and we treat every customer like a friend.\"],\n  [\"Teamwork\", \"Six girls, one goal. We grow better together.\"],\n  [\"Quality\", \"High quality products, a clean and safe space, and results that last.\"],\n];\nconst facts = [[\"6\", \"girls behind every set\"], [\"₱50\", \"nail art starts at\"], [\"Home\", \"service available\"]];\nconst frame = \"bg-white p-2 pb-7 shadow-xl\";\n\nexport default function About() {\n  return (\n    <>\n      {/* HERO */}\n      <section className=\"relative overflow-hidden bg-gradient-to-br from-blush via-petal to-nude/70\">\n        <span aria-hidden=\"true\" className=\"sparkle absolute left-[8%] top-[14%] text-3xl text-gold\">✦</span>\n        <span aria-hidden=\"true\" className=\"sparkle absolute bottom-[12%] right-[10%] text-2xl text-rose\" style={{ animationDelay: \"1s\" }}>✦</span>\n        <div className=\"mx-auto grid max-w-5xl items-center gap-10 px-5 py-14 md:grid-cols-2 md:py-20\">\n          <div>\n            <img src={logo} alt=\"Nails by Glossy Six logo\" className=\"h-28 w-28 rounded-full border-4 border-white object-cover shadow-lg\" />\n            <p className=\"mt-6 font-script text-3xl text-rose\">Our story</p>\n            <h1 className=\"mt-1 text-4xl font-bold leading-tight sm:text-5xl\">Six girls. One glossy goal.</h1>\n            <p className=\"mt-5 max-w-md text-lg\">\n              Nails by Glossy Six started with six girls who love creating beautiful, creative nail designs, and a simple wish: pretty nails shouldn't cost too much.\n            </p>\n          </div>\n          <div className=\"relative mx-auto h-[26rem] w-full max-w-sm\" aria-hidden=\"true\">\n            <figure className={`absolute left-0 top-6 w-44 -rotate-6 ${frame}`}><img src=\"/images/gel-ombre.jpg\" alt=\"\" className=\"aspect-[4/5] w-full object-cover\" /></figure>\n            <figure className={`absolute right-0 top-0 w-44 rotate-6 ${frame}`}><img src=\"/images/art-3d.jpg\" alt=\"\" className=\"aspect-[4/5] w-full object-cover\" /></figure>\n            <figure className={`absolute bottom-0 left-1/4 z-10 w-48 rotate-2 ${frame}`}><img src=\"/images/art-fullset.jpg\" alt=\"\" className=\"aspect-[4/5] w-full object-cover\" /></figure>\n          </div>\n        </div>\n      </section>\n\n      {/* FACTS */}\n      <section className=\"bg-rose text-white\">\n        <dl className=\"mx-auto grid max-w-5xl grid-cols-3 gap-4 px-5 py-6 text-center\">\n          {facts.map(([n, l]) => (\n            <div key={l}><dt className=\"font-display text-3xl font-bold sm:text-4xl\">{n}</dt><dd className=\"text-sm sm:text-base\">{l}</dd></div>\n          ))}\n        </dl>\n      </section>\n\n      {/* STORY */}\n      <section className=\"mx-auto max-w-3xl px-5 py-16 text-center\">\n        <p className=\"font-script text-4xl text-rose sm:text-5xl\">Your beauty, your style, your shine.</p>\n        <p className=\"mt-6 text-lg\">\n          We noticed that many students, teens and young adults love nail art but can't always afford to try new designs. So we made a nail art service that is cute, creative and easy on the wallet.\n        </p>\n        <p className=\"mt-4 text-lg\">\n          Today we share our work online and keep doing what we love: making you feel happy and confident with your nails.\n        </p>\n      </section>\n\n      {/* VISION + MISSION */}\n      <section className=\"mx-auto grid max-w-5xl gap-5 px-5 md:grid-cols-2\">\n        <div className=\"rounded-[2rem] bg-rose p-8 text-white\">\n          <h2 className=\"text-3xl font-bold\">Our vision</h2>\n          <p className=\"mt-3 text-lg\">To be the go-to nail art brand for students and young adults, known for creative designs and prices everyone can enjoy.</p>\n        </div>\n        <div className=\"rounded-[2rem] bg-nude p-8\">\n          <h2 className=\"text-3xl font-bold text-rose\">Our mission</h2>\n          <p className=\"mt-3 text-lg\">To give customers pretty, well-made nails at an affordable price, and to make every visit a happy and confident moment.</p>\n        </div>\n      </section>\n\n      {/* VALUES */}\n      <section className=\"mx-auto max-w-5xl px-5 py-16\">\n        <h2 className=\"text-center text-3xl font-bold sm:text-4xl\">What we value</h2>\n        <ul className=\"mt-8 grid gap-4 sm:grid-cols-2 lg:grid-cols-3\">\n          {values.map(([t, d], i) => (\n            <li key={t} className=\"rounded-3xl border border-blush bg-white p-6 shadow-sm\">\n              <span className=\"font-display text-sm font-bold text-gold\">0{i + 1} ✦</span>\n              <p className=\"mt-1 font-display text-xl font-bold text-rose\">{t}</p>\n              <p className=\"mt-1\">{d}</p>\n            </li>\n          ))}\n        </ul>\n      </section>\n\n      {/* CUSTOMER REVIEWS */}\n      <Reviews />\n\n      {/* GALLERY */}\n      <section className=\"bg-blush/40\">\n        <div className=\"mx-auto max-w-5xl px-5 py-16\">\n          <h2 className=\"text-3xl font-bold sm:text-4xl\">Our work</h2>\n          <p className=\"font-script text-2xl text-rose\">Made with love, one set at a time.</p>\n          <div className=\"mt-8 columns-2 gap-3 sm:columns-3 lg:columns-4\">\n            {gallery.map((src) => (\n              <img key={src} src={src} alt=\"Nails by Glossy Six work\" loading=\"lazy\" className=\"mb-3 w-full break-inside-avoid rounded-2xl object-cover shadow-sm\" />\n            ))}\n          </div>\n        </div>\n      </section>\n\n      {/* CTA */}\n      <section className=\"mx-auto max-w-5xl px-5 py-16\">\n        <div className=\"rounded-[2rem] bg-gradient-to-r from-rose to-[#C97A8E] px-6 py-12 text-center text-white\">\n          <p className=\"font-script text-3xl\">Home service available</p>\n          <h2 className=\"mt-1 text-3xl font-bold sm:text-4xl\">We bring your nail glow to you!</h2>\n          <div className=\"mt-6 flex flex-wrap justify-center gap-3\">\n            <Link to=\"/book\" className=\"btn bg-white text-rose hover:bg-blush\">Book your slot</Link>\n            <Link to=\"/services\" className=\"btn border border-white/70 hover:bg-white/10\">See services</Link>\n          </div>\n        </div>\n      </section>\n    </>\n  );\n}\n",
 "src/pages/Home.jsx": "import { Link } from \"react-router-dom\";\nimport NailRow from \"../components/NailRow.jsx\";\n\nconst sparkles = [\n  [\"left-[6%] top-[12%]\", \"0s\", \"text-3xl\"], [\"right-[8%] top-[10%]\", \".8s\", \"text-2xl\"],\n  [\"left-[45%] top-[4%]\", \"1.4s\", \"text-xl\"], [\"right-[30%] bottom-[10%]\", \"2s\", \"text-3xl\"],\n  [\"left-[10%] bottom-[8%]\", \"1s\", \"text-2xl\"],\n];\nconst ticker = [\"Pretty nails\", \"Affordable\", \"Hand-painted\", \"Student-friendly\", \"Made by six girls\"];\nconst pages = [\n  [\"/about\", \"About\", \"Our story, vision, mission and values.\"],\n  [\"/services\", \"Services\", \"See what we offer and book your slot.\"],\n  [\"/contact\", \"Contact\", \"Email, location and map.\"],\n];\n\nexport default function Home() {\n  return (\n    <>\n      {/* HERO */}\n      <section className=\"relative overflow-hidden bg-gradient-to-br from-blush via-petal to-nude/70\">\n        {sparkles.map(([pos, d, size], i) => (\n          <span key={i} aria-hidden=\"true\" className={`sparkle absolute ${pos} ${size} text-rose`} style={{ animationDelay: d }}>✦</span>\n        ))}\n        <div className=\"relative mx-auto grid max-w-5xl items-center gap-10 px-5 py-16 md:grid-cols-[1.2fr_1fr] md:py-24\">\n          <div>\n            <p className=\"inline-block rounded-full bg-white/70 px-4 py-1 text-sm font-medium text-rose\">\n              Nail art in San Fernando, Pampanga · Home service\n            </p>\n            <h1 className=\"mt-5 text-5xl font-bold leading-[1.05] sm:text-6xl\">\n              <span className=\"italic text-rose\">Pretty nails,</span><br />priced for students.\n            </h1>\n            <p className=\"mt-5 max-w-md text-lg\">\n              Six girls, one glossy goal: cute, creative nail art that makes you feel happy and confident.\n            </p>\n            <div className=\"mt-8 flex flex-wrap gap-3\">\n              <Link to=\"/book\" className=\"btn btn-primary shadow-lg shadow-rose/30\">Book now</Link>\n              <Link to=\"/services\" className=\"btn bg-white/80 hover:bg-white\">See services</Link>\n            </div>\n          </div>\n          <div className=\"scale-110 py-6\"><NailRow /></div>\n        </div>\n      </section>\n\n      {/* TICKER */}\n      <div className=\"overflow-hidden bg-rose py-3 text-white\" aria-hidden=\"true\">\n        <div className=\"marquee flex w-max gap-10 whitespace-nowrap font-display text-lg italic\">\n          {[...ticker, ...ticker, ...ticker, ...ticker].map((t, i) => <span key={i}>✦ {t}</span>)}\n        </div>\n      </div>\n\n      {/* PAGE LINKS (details live on their own pages) */}\n      <section className=\"mx-auto max-w-5xl px-5 py-16\">\n        <div className=\"grid gap-4 sm:grid-cols-3\">\n          {pages.map(([to, title, line]) => (\n            <Link key={to} to={to} className=\"rounded-3xl bg-blush/60 p-7 transition hover:-translate-y-1 hover:bg-blush\">\n              <p className=\"font-display text-2xl font-bold\">{title}</p>\n              <p className=\"mt-2\">{line}</p>\n              <p className=\"mt-4 font-medium text-rose\">Open &rarr;</p>\n            </Link>\n          ))}\n        </div>\n      </section>\n    </>\n  );\n}\n"
};
const images = {"public/images/gel-french.jpg": "", "public/images/art-3d.jpg": "", "public/images/gel-custom.jpg": "", "public/images/builder-color.jpg": "", "public/images/builder-natural.jpg": "", "public/images/gel-natural.jpg": "", "public/images/more-pedi.jpg": "", "public/images/gel-ombre.jpg": "", "public/images/logo.jpg": "", "public/images/builder-design.jpg": "", "public/images/art-detailed.jpg": "", "public/images/gel-chrome.jpg": "", "public/images/more-gel.jpg": "", "public/images/art-seasonal.jpg": "", "public/images/art-fullset.jpg": "", "public/images/more-repair.jpg": "", "public/images/art-simple.jpg": ""};

const root = process.cwd();
if (!fs.existsSync(path.join(root, "package.json"))) {
  console.error("Run this inside your glossy-six folder (the one that has package.json).");
  process.exit(1);
}
const backup = path.join(root, ".backup-before-update");
let written = 0, kept = 0;

function put(rel, data, same) {
  const target = path.join(root, rel);
  if (fs.existsSync(target)) {
    if (same(fs.readFileSync(target))) { kept++; return; }
    const b = path.join(backup, rel);
    fs.mkdirSync(path.dirname(b), { recursive: true });
    fs.copyFileSync(target, b);
  }
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, data);
  written++;
  console.log("updated", rel);
}

for (const [rel, content] of Object.entries(files)) {
  if (rel === "update.mjs") continue;
  let text = content;
  if (rel === "src/data.js") {
    // New menu and prices come from your poster. Keep YOUR social links if you already set them.
    const old = fs.existsSync(path.join(root, rel)) ? fs.readFileSync(path.join(root, rel), "utf8") : "";
    const re = /socials:\s*\[[\s\S]*?\n  \],/;
    if (old.match(re)) text = text.replace(re, () => old.match(re)[0]);
  }
  put(rel, text, (buf) => buf.toString("utf8") === text);
}
for (const [rel, b64] of Object.entries(images)) {
  const buf = Buffer.from(b64, "base64");
  put(rel, buf, (cur) => Buffer.compare(cur, buf) === 0);
}

console.log(`\nDone. ${written} file(s) written, ${kept} already up to date.`);
if (written && fs.existsSync(backup)) console.log("Your old versions are saved in .backup-before-update");
console.log("Next: npm install   then   npm run dev");
